import sys

def is_palindrome(s):
    return s == s[::-1]

def count_insertion_positions(s):
    n = len(s)
    count = 0
    for i in range(n + 1):
        if is_palindrome(s[:i] + s[i:]):
            count += 1
    return count

def main():
    import sys
    input = sys.stdin.read().split()
    T = int(input[0])
    results = []
    index = 1
    for _ in range(T):
        S = input[index]
        results.append(count_insertion_positions(S))
        index += 1
    for result in results:
        print(result)

main()
